//! Export the Rust-canonical `airi-channel` wire types to TypeScript.
//!
//! ```sh
//! cargo run -p airi-channel --example export-wire-types          # rewrite the generated file
//! cargo run -p airi-channel --example export-wire-types -- --check   # fail if it drifted
//! ```
//!
//! The generated file is checked in at
//! `packages/server-shared/src/types/generated/airi-channel.ts` and
//! re-exported from `@proj-airi/server-shared/types`. Never edit it by
//! hand; change the Rust types in `src/wire.rs`, `src/control.rs` or
//! `src/config.rs` and re-run the exporter.

use std::path::{Path, PathBuf};

const TARGET: &str = "packages/server-shared/src/types/generated/airi-channel.ts";

const HEADER: &str = "// SPDX-License-Identifier: GPL-3.0-or-later\n\
                       // DO NOT EDIT — generated by `cargo run -p airi-channel --example export-wire-types`.\n\
                       // Sources of truth: crates/airi-channel/src/wire.rs (frames), crates/airi-channel/src/control.rs and crates/airi-channel/src/config.rs (gateway control plane).\n\n";

fn target_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .join(TARGET)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let out = target_path();
    let check = std::env::args().skip(1).any(|arg| arg == "--check");

    let types = airi_channel::wire::type_collection();
    // NOTICE: `Format` (unified) — our frames serialize and deserialize with
    // the same shape; `PhasesFormat` would split duplicates needlessly.
    let content = specta_typescript::Typescript::default()
        .header(HEADER)
        .export(&types, specta_serde::Format)?;

    if check {
        let current = std::fs::read_to_string(&out).map_err(|e| {
            format!(
                "cannot read {}: {e} (run the exporter once to create it)",
                out.display()
            )
        })?;
        if current != content {
            eprintln!(
                "error: {TARGET} is stale. Run `cargo run -p airi-channel --example export-wire-types` and commit the result."
            );
            std::process::exit(1);
        }
        println!("ok: {TARGET} is up to date");
        return Ok(());
    }

    if let Some(parent) = out.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(&out, content)?;
    println!("wrote {}", out.display());
    Ok(())
}
